solution:
function grade(score) {
  // Check from the highest band down: the first true condition wins.
  if (score >= 90) {
    return "A";
  } else if (score >= 70) {
    return "B";
  } else if (score >= 50) {
    return "C";
  } else {
    return "F";
  }
}

