solution:
function dayType(day) {
  switch (day) {
    // Empty cases fall through to the next one: several values share the same code.
    case "sat":
    case "sun":
      return "weekend";
    case "mon":
    case "tue":
    case "wed":
    case "thu":
    case "fri":
      return "weekday";
    default:
      return "unknown";
  }
}

