function countVowels(text) {
  let count = 0;
  // for...of gives one character of the string in each round.
  for (let ch of text) {
    if (ch === "a" || ch === "e" || ch === "i" || ch === "o" || ch === "u") {
      count++;
    }
  }
  return count;
}

