solution:
function fizzBuzz(n) {
  let result = [];
  for (let i = 1; i <= n; i++) {
    // The most specific case (multiple of 3 AND 5) must be checked first.
    if (i % 3 === 0 && i % 5 === 0) {
      result.push("FizzBuzz");
    } else if (i % 3 === 0) {
      result.push("Fizz");
    } else if (i % 5 === 0) {
      result.push("Buzz");
    } else {
      result.push(String(i));
    }
  }
  return result;
}

console.log(fizzBuzz(5).join(" "));

alternatives:
