  let result = [];
  for (let i = 1; i <= n; i++) {
    let text = "";
    if (i % 3 === 0) text += "Fizz";
    if (i % 5 === 0) text += "Buzz";
    if (text === "") text = String(i);
    result.push(text);
  }
  return result;
}

