solution:
function firstNegative(numbers) {
  let position = -1; // -1 means "not found yet"
  for (let i = 0; i < numbers.length; i++) {
    if (numbers[i] < 0) {
      position = i;
      break; // stop at the first one: the later ones don't matter
    }
  }
  return position;
}

