solution:
function collatzSteps(n) {
  let steps = 0;
  // We don't know in advance how many rounds we need: a while loop fits.
  while (n !== 1) {
    if (n % 2 === 0) {
      n = n / 2;
    } else {
      n = n * 3 + 1;
    }
    steps++; // count every change; without it the answer is always 0
  }
  return steps;
}

console.log(collatzSteps(6));

