console.log(stars(3));

solution:
function stars(n) {
  let result = "";
  for (let row = 1; row <= n; row++) {
    // The inner loop draws as many stars as the row number.
    for (let i = 1; i <= row; i++) {
      result += "*";
    }
    // Line break between rows, but not after the last one.
    if (row < n) {
      result += "\n";
    }
  }
  return result;
}

console.log(stars(3));

alternatives:
function stars(n) {
  let rows = [];
  let line = "";
  for (let row = 1; row <= n; row++) {
    line += "*";
    rows.push(line);
  }
  return rows.join("\n");
}

console.log(stars(3));

