solution:
function countDigits(n) {
  let digits = 0;
  // do...while runs at least once, so 0 counts as one digit.
  do {
    n = Math.floor(n / 10); // drop the last digit: 305 -> 30 -> 3 -> 0
    digits++;
  } while (n > 0);
  return digits;
}

console.log(countDigits(305));

